#!/usr/bin/env python3
# Sammel-Bereinigung nach Blackout-Radar Schritt 5.
# Die vier Pi-Dateien bleiben, wenn ihr Hash stimmt. Kein Mesh, keine Abschaltung.
from __future__ import annotations
import base64, hashlib, os, shutil, sys, time
from datetime import datetime, timedelta
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
PI = {
    "dashboard.py": ("239bdf4d0f761325", 1392013),
    "blackout_radar.py": ("ca4ba683896bc5a5", 70067),
    "lage_pages.py": ("b74f3abcb5377023", 230878),
    "pushover_push.py": ("2267a556ab7bb27f", 12129),
}
DOCS = "prepper_docs.py"
ARCHIV = "apply-archiv"
BAKARCH = "bak-archiv"

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def load():
    raw = PAYLOAD_JSON
    return base64.b64decode(raw["old"]), base64.b64decode(raw["new"])

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin Minute %02d" % m

def geschuetzt(path: Path, wurzel: Path) -> bool:
    rel = path.relative_to(wurzel).as_posix().lower()
    name = path.name.lower()
    if rel.startswith("static/") or rel == "static":
        return True
    if "pinneberg" in name or "pinneberg" in rel:
        return True
    if name.endswith(".db") or name.endswith(".db-wal") or name.endswith(".db-shm"):
        return True
    if name.endswith(".cfg") or name in ("pushover.cfg", "usv_eg.json"):
        return True
    if name.endswith(".json"):
        return True
    return False

def basisname(name: str) -> str:
    i = name.lower().find(".bak")
    return name[:i] if i > 0 else name

def liste(wurzel: Path):
    fund = []
    for pfad in wurzel.rglob("*"):
        if not pfad.is_file() or pfad.is_symlink():
            continue
        rel = pfad.relative_to(wurzel).as_posix()
        if rel.startswith(ARCHIV + "/") or rel.startswith(BAKARCH + "/") or rel.startswith("venv/") or "/__pycache__/" in ("/" + rel):
            continue
        fund.append(pfad)
    return fund

def plan(wurzel: Path):
    zeilen = []
    for pfad in liste(wurzel):
        rel = pfad.relative_to(wurzel)
        groesse = pfad.stat().st_size
        if geschuetzt(pfad, wurzel):
            zeilen.append((pfad, None, "geschuetzt", groesse))
            continue
        name = pfad.name
        if name.startswith("apply-") and name.endswith(".py") and name != "apply-sammel-bereinigung.py":
            zeilen.append((pfad, wurzel / ARCHIV / name, "apply", groesse))
        elif ".bak" in name.lower():
            zeilen.append((pfad, None, "bak-kandidat", groesse))
    gruppen = {}
    for pfad, _ziel, art, groesse in zeilen:
        if art != "bak-kandidat":
            continue
        key = (pfad.parent, basisname(pfad.name))
        gruppen.setdefault(key, []).append(pfad)
    behalten = set()
    for _key, pfade in gruppen.items():
        neueste = max(pfade, key=lambda p: (p.stat().st_mtime, p.name))
        behalten.add(neueste)
    fertig = []
    for pfad, ziel, art, groesse in zeilen:
        if art != "bak-kandidat":
            fertig.append((pfad, ziel, art, groesse))
            continue
        if pfad in behalten:
            fertig.append((pfad, None, "bak-neueste", groesse))
        else:
            fertig.append((pfad, wurzel / BAKARCH / pfad.name, "bak-alt", groesse))
    return fertig

def alt_genug(pfad: Path, jetzt: datetime) -> bool:
    alter = datetime.fromtimestamp(pfad.stat().st_mtime)
    return jetzt - alter > timedelta(days=30)

def loeschplan(wurzel: Path, jetzt: datetime):
    aus = []
    for ordner in (wurzel / ARCHIV, wurzel / BAKARCH):
        if not ordner.is_dir():
            continue
        for pfad in ordner.rglob("*"):
            if not pfad.is_file() or pfad.is_symlink() or geschuetzt(pfad, wurzel):
                continue
            if alt_genug(pfad, jetzt):
                aus.append((pfad, pfad.stat().st_size))
    return aus

def zeigen(zeilen, loesch, loeschen):
    for pfad, ziel, art, groesse in zeilen:
        if art in ("apply", "bak-alt"):
            print("verschieben %s (%d B) -> %s" % (pfad, groesse, ziel))
        elif art == "bak-neueste":
            print("behalten %s (%d B)" % (pfad, groesse))
        elif art == "geschuetzt":
            if ".bak" in pfad.name.lower() or pfad.name.startswith("apply-"):
                print("geschuetzt %s (%d B)" % (pfad, groesse))
    if loeschen:
        for pfad, groesse in loesch:
            print("loeschen %s (%d B)" % (pfad, groesse))
    else:
        print("Loeschen aelter als 30 Tage ist aus. Option: --loeschen-alt")

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    bak = path.with_name(path.name + ".bak-sammel-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")

def schreiben(path: Path, data: bytes):
    tmp = path.with_name("." + path.name + ".tmp-sammel")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, path.stat().st_mode & 0o777)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def docs_ziel(data: bytes):
    old, neu = load()
    if data.count(neu) == 1 and data.count(old) == 0:
        return data
    if data.count(old) != 1 or data.count(neu) != 0:
        raise RuntimeError("Stelle")
    return data.replace(old, neu, 1)

def apply_dir(ordner: Path, dry: bool, kein: bool, loeschen: bool, jetzt=None) -> int:
    fehlt = False
    for name, (kopf, laenge) in PI.items():
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
        data = pfad.read_bytes()
        ist = sha(data)
        print("%s sha16 %s bytes %d" % (name, ist[:16], len(data)))
        if not ist.startswith(kopf) or len(data) != laenge:
            print("STOP: %s %s ist nicht die Basis" % (name, ist[:16]))
            fehlt = True
    if fehlt:
        return 2
    print("Hand-Fixes sind in den vier Dateien, sie werden nicht geschrieben.")
    dok = ordner / DOCS
    if dok.is_symlink() or not dok.is_file():
        print("STOP: prepper_docs.py fehlt")
        return 2
    try:
        ziel = docs_ziel(dok.read_bytes())
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    print("prepper_docs.py endstand sha16 %s bytes %d" % (sha(ziel)[:16], len(ziel)))
    bewegung = plan(ordner)
    loesch = loeschplan(ordner, jetzt or datetime.now())
    zeigen(bewegung, loesch, loeschen)
    frei, meldung = fenster(jetzt)
    print(meldung)
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Verschieben, kein Loeschen, kein Neustart")
        return 0
    if not frei:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    try:
        if dok.read_bytes() != ziel:
            sichern(dok, dok.read_bytes())
            schreiben(dok, ziel)
            print("geschrieben prepper_docs.py")
        else:
            print("prepper_docs.py ist schon der Sollwert")
        for pfad, zielpfad, art, _groesse in bewegung:
            if art not in ("apply", "bak-alt"):
                continue
            zielpfad.parent.mkdir(parents=True, exist_ok=True)
            if zielpfad.exists():
                zielpfad = zielpfad.with_name(zielpfad.name + "-doppelt")
            shutil.move(str(pfad), str(zielpfad))
        if loeschen:
            for pfad, _groesse in loeschplan(ordner, jetzt or datetime.now()):
                pfad.unlink()
                print("geloescht %s" % pfad)
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    for name in PI:
        data = (ordner / name).read_bytes()
        print("%s endstand sha16 %s bytes %d" % (name, sha(data)[:16], len(data)))
    if kein:
        print("Kein Neustart in dieser Pruefung.")
    else:
        print("Kein Neustart. Die vier Dienst-Dateien sind unveraendert.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 13, 12, 12))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 45))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 0))[0]
    import tempfile
    wurzel = Path(tempfile.mkdtemp(prefix="sammel-"))
    (wurzel / "static").mkdir()
    (wurzel / "static" / "apply-alt.py").write_bytes(b"static")
    (wurzel / "apply-alt.py").write_bytes(b"alt")
    (wurzel / "apply-sammel-bereinigung.py").write_bytes(b"selbst")
    (wurzel / "dashboard.py.bak-alt").write_bytes(b"alt")
    neu = wurzel / "dashboard.py.bak-neu"
    neu.write_bytes(b"neu")
    os.utime(neu, (time.time(), time.time()))
    (wurzel / "lagezentrum.db").write_bytes(b"db")
    (wurzel / "lagezentrum.db-wal").write_bytes(b"wal")
    (wurzel / "pushover.cfg").write_bytes(b"cfg")
    (wurzel / "usv_eg.json").write_bytes(b"{}")
    (wurzel / "blackout_radar_targets.json").write_bytes(b"{}")
    (wurzel / "pinneberg_rolle.py.bak-alt").write_bytes(b"pn")
    zeilen = plan(wurzel)
    arten = {pfad.relative_to(wurzel).as_posix(): art for pfad, _z, art, _g in zeilen}
    assert arten["apply-alt.py"] == "apply"
    assert arten["static/apply-alt.py"] == "geschuetzt"
    assert "apply-sammel-bereinigung.py" not in arten
    assert arten["dashboard.py.bak-neu"] == "bak-neueste"
    assert arten["dashboard.py.bak-alt"] == "bak-alt"
    assert arten["lagezentrum.db"] == "geschuetzt"
    assert arten["pushover.cfg"] == "geschuetzt"
    assert arten["usv_eg.json"] == "geschuetzt"
    assert arten["pinneberg_rolle.py.bak-alt"] == "geschuetzt"
    assert not any(p.name == "apply-alt.py" and art != "geschuetzt" for p, _z, art, _g in plan(wurzel / "static") if False)
    assert all(geschuetzt(wurzel / "static" / "apply-alt.py", wurzel) for _ in (0,))
    (wurzel / ARCHIV).mkdir()
    alt = wurzel / ARCHIV / "apply-uralt.py"
    alt.write_bytes(b"uralt")
    os.utime(alt, (time.time() - 40 * 86400, time.time() - 40 * 86400))
    assert any(p.name == "apply-uralt.py" for p, _g in loeschplan(wurzel, datetime.now()))
    assert loeschplan(wurzel, datetime.now() - timedelta(days=50)) == []
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = loeschen = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--loeschen-alt":
            loeschen = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein, loeschen)

PAYLOAD_JSON = {"old":"","new":""}

if __name__ == "__main__":
    sys.exit(main(sys.argv))
